  function draw(now){
    ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#070d22';ctx.fillRect(0,0,canvas.width,canvas.height);
    for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){
      const px=x*TILE,py=y*TILE,cell=board[y][x];
      if(cell==='#'){
        ctx.fillStyle='#101d43';ctx.beginPath();ctx.roundRect(px+1.5,py+1.5,TILE-3,TILE-3,5);ctx.fill();
        ctx.strokeStyle='#3155a1';ctx.lineWidth=1.15;ctx.beginPath();ctx.roundRect(px+3,py+3,TILE-6,TILE-6,4);ctx.stroke();
        ctx.fillStyle='#233d76';ctx.fillRect(px+6,py+5,Math.max(3,TILE-12),1);
      }else if(cell==='.'||cell==='o'){
        const big=cell==='o',pulse=big?(.72+Math.sin(now/145)*.22):1;
        ctx.fillStyle=big?'#ffe77a':'#d7e3ff';ctx.shadowColor=big?'#ffe24a':'#c6dcff';ctx.shadowBlur=big?13:4;ctx.beginPath();ctx.arc(px+TILE/2,py+TILE/2,big?5.3*pulse:2.05,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
      }
    }
    drawPac(now);ghosts.forEach(g=>drawGhost(g,now));
    if(state==='hit'){ctx.fillStyle='#ff446e22';ctx.fillRect(0,0,canvas.width,canvas.height)}
  }
  function drawPac(now){
    const cx=(player.x+.5)*TILE,cy=(player.y+.5)*TILE,r=9.4,d=dirs[player.dir],opening=(.14+Math.abs(Math.sin(now/75))*.28);
    ctx.save();ctx.translate(cx,cy);ctx.rotate(d.angle);ctx.shadowColor='#ffe24a';ctx.shadowBlur=15;ctx.fillStyle='#ffe24a';ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,r,opening*Math.PI, (2-opening)*Math.PI);ctx.closePath();ctx.fill();ctx.restore();ctx.shadowBlur=0;
  }
  function drawGhost(g,now){
    const cx=(g.x+.5)*TILE,cy=(g.y+.5)*TILE,r=9.4,fright=now<powerUntil,color=fright?(Math.floor(now/220)%2?'#f2f5ff':'#5075ff'):g.color;
    ctx.save();ctx.translate(cx,cy);ctx.shadowColor=color;ctx.shadowBlur=fright?10:12;ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,-1,r,Math.PI,0);ctx.lineTo(r,8);ctx.lineTo(r*.5,5);ctx.lineTo(0,8);ctx.lineTo(-r*.5,5);ctx.lineTo(-r,8);ctx.closePath();ctx.fill();ctx.shadowBlur=0;
    ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(-3.3,-1,2.6,3.4,0,0,Math.PI*2);ctx.ellipse(3.3,-1,2.6,3.4,0,0,Math.PI*2);ctx.fill();
    if(fright){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-3,-1,1,0,Math.PI*2);ctx.arc(3,-1,1,0,Math.PI*2);ctx.fill()}else{const look=dirs[g.dir];ctx.fillStyle='#27315c';ctx.beginPath();ctx.arc(-3.1+look.x*1,-1+look.y*1,1.35,0,Math.PI*2);ctx.arc(3.1+look.x*1,-1+look.y*1,1.35,0,Math.PI*2);ctx.fill()}
    ctx.restore();
  }
  function loop(now){
    if(state!=='playing')return;
    const delta=Math.min(now-lastTime,80);lastTime=now;playerClock+=delta;ghostClock+=delta;
    if(playerClock>=125){playerClock-=125;movePlayer();mouth++}
    if(ghostClock>=155){ghostClock-=155;ghosts.forEach(g=>ghostStep(g,now));if(collision(now)){} }
    draw(now);if(state==='playing')requestAnimationFrame(loop);
  }
  function setDirection(dir){if(!dirs[dir])return;player.next=dir;if(state==='ready'){draw(performance.now())}else if(state==='paused')togglePause()}
  window.addEventListener('keydown',e=>{
    const keys={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};
    if(keys[e.key]){e.preventDefault();setDirection(keys[e.key]);if(state==='ready')begin();return}
    if(e.code==='Space'){e.preventDefault();if(state==='playing'||state==='paused')togglePause();else if(state==='ready'||state==='gameover'||state==='won')begin()}
    if(e.key==='Escape'||e.key==='p'||e.key==='P')togglePause();
  });
  document.querySelectorAll('.ctrl').forEach(button=>{
    const act=e=>{e.preventDefault();setDirection(button.dataset.dir);if(state==='ready')begin()};
    button.addEventListener('pointerdown',act);button.addEventListener('contextmenu',e=>e.preventDefault());
  });
  startBtn.addEventListener('click',()=>{if(state==='paused')togglePause();else begin()});
  document.querySelector('#pauseBtn').addEventListener('click',togglePause);
  document.querySelector('#soundBtn').addEventListener('click',()=>{soundOn=!soundOn;document.querySelector('#soundState').textContent=soundOn?'ON':'OFF';document.querySelector('#soundBtn').textContent=soundOn?'♫':'♩';if(soundOn)sound(600,.08)});
  newBoard();resetActors();updateHud();draw(0);
})();
</script>
</body>
</html>

