(() => {
const source=['###################','#........#........#','#.##.##..#..##.##.#','#.................#','#.##.#.#####.#.##.#','#....#...#...#....#','####.###.#.###.####','   #.#.......#.#   ','####.#.##.##.#.####','    .#.#   #.#.    ','####.#.#####.#.####','#....#... ...#....#','#.##.###.#.###.##.#','#o...#...#...#...o#','###..#.#.#.#.#..###','#......#...#......#','#.####.#.#.#.####.#','#.................#','#.##.##..#..##.##.#','#........#........#','###################'];
const TILE=24,ROWS=source.length,COLS=source[0].length,canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');canvas.width=COLS*TILE;canvas.height=ROWS*TILE;
const $=s=>document.querySelector(s),scoreEl=$('#score'),bestEl=$('#best'),livesEl=$('#lives'),overlay=$('#overlay');
const dirs={up:{x:0,y:-1,angle:-Math.PI/2},right:{x:1,y:0,angle:0},down:{x:0,y:1,angle:Math.PI/2},left:{x:-1,y:0,angle:Math.PI}};
let board,player,ghosts,score=0,lives=3,best=Number(localStorage.getItem('midnight-pac-best')||0),dots=0,powerUntil=0,state='ready',last=0,pClock=0,gClock=0,soundOn=true,audio;
bestEl.textContent=String(best).padStart(6,'0');
function newBoard(){board=source.map(row=>row.split(''));dots=0;for(let row of board)for(let c of row)if(c==='.'||c==='o')dots++}
function resetActors(){player={x:9,y:15,dir:'left',next:'left'};ghosts=[{x:8,y:11,color:'#ff5e9f',dir:'left',delay:0},{x:10,y:11,color:'#58e5ff',dir:'right',delay:850},{x:8,y:17,color:'#ff9c4a',dir:'up',delay:1700},{x:10,y:17,color:'#bb85ff',dir:'left',delay:2500}];pClock=gClock=0}
function open(x,y){return y>=0&&y<ROWS&&x>=0&&x<COLS&&board[y][x]!=='#'&&board[y][x]!==' '}
function hud(){scoreEl.textContent=String(score).padStart(6,'0');bestEl.textContent=String(best).padStart(6,'0');livesEl.textContent=lives>0?Array(lives).fill('♥').join(' '):'—'}
function beep(freq=420,duration=.06,type='square',vol=.035){if(!soundOn)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(vol,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch(_){}}
function add(points){score+=points;if(score>best){best=score;localStorage.setItem('midnight-pac-best',best)}hud()}
function begin(){if(state==='gameover'||state==='won'){score=0;lives=3;newBoard();resetActors();hud()}state='playing';overlay.classList.add('hidden');$('#statusText').textContent='Caçando pastilhas';last=performance.now();requestAnimationFrame(loop);beep(520,.08)}
function show(kind){state=kind;overlay.classList.remove('hidden');const title=$('#overlayTitle'),eye=$('#overlayEyebrow'),text=$('#overlayText'),button=$('#startBtn');if(kind==='paused'){eye.textContent='Respire fundo';title.innerHTML='JOGO <em>PAUSADO</em>';text.textContent='Os fantasmas também deram uma pausa. Volte quando estiver pronto.';button.textContent='Continuar';$('#statusText').textContent='Jogo pausado'}else if(kind==='gameover'){eye.textContent='Fim de jogo';title.innerHTML='FIM DE <em>JOGO</em>';text.textContent=`Você marcou ${score.toLocaleString('pt-BR')} pontos. Mais uma rodada?`;button.textContent='Jogar novamente';$('#statusText').textContent='Partida encerrada'}else if(kind==='won'){eye.textContent='Labirinto completo';title.innerHTML='VOCÊ <em>VENCEU!</em>';text.textContent=`Incrível! Você limpou o labirinto com ${score.toLocaleString('pt-BR')} pontos.`;button.textContent='Jogar novamente';$('#statusText').textContent='Vitória!'}}
