function collect(){const c=board[player.y][player.x];if(c==='.'||c==='o'){board[player.y][player.x]=' ';dots--;if(c==='o'){powerUntil=performance.now()+7000;add(50);beep(180,.2,'sawtooth',.045)}else{add(10);if(score%50===0)beep(420,.035)}if(score>=10000&&Math.floor((score-10)/10000)<Math.floor(score/10000))lives++;hud();if(dots<=0)show('won')}}
function movePlayer(){if(open(player.x+dirs[player.next].x,player.y+dirs[player.next].y))player.dir=player.next;const d=dirs[player.dir];if(open(player.x+d.x,player.y+d.y)){player.x+=d.x;player.y+=d.y;collect()}}
function stepGhost(g,now){if(g.delay>0){g.delay-=155;return}let options=Object.keys(dirs).filter(k=>open(g.x+dirs[k].x,g.y+dirs[k].y));if(options.length>1){const reverse={up:'down',down:'up',left:'right',right:'left'}[g.dir],forward=options.filter(k=>k!==reverse);if(forward.length)options=forward}if(!options.length)return;const scared=now<powerUntil,rank=options.map(k=>({key:k,dist:Math.abs(g.x+dirs[k].x-player.x)+Math.abs(g.y+dirs[k].y-player.y)})).sort((a,b)=>scared?b.dist-a.dist:a.dist-b.dist),ties=rank.filter(v=>v.dist===rank[0].dist),choice=Math.random()<.2?ties[Math.floor(Math.random()*ties.length)]:rank[0];g.dir=choice.key;g.x+=dirs[g.dir].x;g.y+=dirs[g.dir].y}
function collision(now){for(const g of ghosts)if(g.x===player.x&&g.y===player.y){if(now<powerUntil){g.x=9;g.y=15;g.delay=900;add(200);beep(700,.12,'triangle')}else{lives--;hud();beep(120,.35,'sawtooth',.06);if(lives<=0)show('gameover');else{resetActors();state='hit';setTimeout(()=>{if(state==='hit'){state='playing';last=performance.now();requestAnimationFrame(loop)}},850)}return true}}return false}

